class Solution {
    static const int MAXV = 100000;

    struct SegTree {
        int n;
        vector<int> mx, lazy;

        SegTree(const vector<int>& a)
            : n((int)a.size()),
              mx(4 * n + 4, 0),
              lazy(4 * n + 4, 0) {
            if (n) build(1, 0, n - 1, a);
        }

        void build(int p, int l, int r,
                   const vector<int>& a) {
            if (l == r) {
                mx[p] = a[l];
                return;
            }

            int m = (l + r) / 2;
            build(p * 2, l, m, a);
            build(p * 2 + 1, m + 1, r, a);

            mx[p] = max(mx[p * 2], mx[p * 2 + 1]);
        }

        void update(int p, int l, int r,
                    int ql, int qr, int v) {
            if (ql <= l && r <= qr) {
                mx[p] += v;
                lazy[p] += v;
                return;
            }

            int m = (l + r) / 2;

            if (ql <= m)
                update(p * 2, l, m, ql, qr, v);

            if (qr > m)
                update(p * 2 + 1, m + 1, r,
                       ql, qr, v);

            mx[p] = lazy[p] +
                    max(mx[p * 2], mx[p * 2 + 1]);
        }

        void add(int l, int r, int v) {
            if (n && l < r)
                update(1, 0, n - 1, l, r - 1, v);
        }

        int maximum() const {
            return n ? mx[1] : 0;
        }
    };

public:
    vector<int> maximumCount(
        vector<int>& nums,
        vector<vector<int>>& queries) {

        int n = nums.size();

        vector<char> prime(MAXV + 1, true);
        prime[0] = prime[1] = false;

        for (int i = 2; i * i <= MAXV; ++i) {
            if (!prime[i]) continue;

            for (int j = i * i; j <= MAXV; j += i)
                prime[j] = false;
        }

        vector<set<int>> positions(MAXV + 1);

        for (int i = 0; i < n; ++i) {
            if (prime[nums[i]])
                positions[nums[i]].insert(i);
        }

        int distinct = 0;
        vector<int> diff(n + 1, 0);

        for (int p = 2; p <= MAXV; ++p) {
            const set<int>& s = positions[p];

            if (s.empty()) continue;

            ++distinct;

            if (s.size() >= 2) {
                int l = *s.begin();
                int r = *s.rbegin();

                ++diff[l];
                --diff[r];
            }
        }

        vector<int> cover(max(0, n - 1), 0);

        int running = 0;

        for (int i = 0; i < n - 1; ++i) {
            running += diff[i];
            cover[i] = running;
        }

        // Direct updates for workloads where
        // scanning is cheaper than tree overhead.
        bool small =
            1LL * n * queries.size() <= 30000000LL;

        SegTree seg(small ? vector<int>() : cover);

        auto addRange = [&](int l, int r, int delta) {
            if (l >= r) return;

            if (small) {
                for (int i = l; i < r; ++i)
                    cover[i] += delta;
            } else {
                seg.add(l, r, delta);
            }
        };

        vector<int> answer;
        answer.reserve(queries.size());

        for (const auto& q : queries) {
            int idx = q[0];
            int val = q[1];
            int old = nums[idx];

            if (old != val) {

                if (prime[old]) {
                    set<int>& s = positions[old];

                    int oldL = *s.begin();
                    int oldR = *s.rbegin();

                    s.erase(idx);

                    if (s.empty()) {
                        --distinct;
                        addRange(oldL, oldR, -1);
                    } else {
                        int newL = *s.begin();
                        int newR = *s.rbegin();

                        addRange(oldL, newL, -1);
                        addRange(newR, oldR, -1);
                    }
                }

                if (prime[val]) {
                    set<int>& s = positions[val];

                    if (s.empty()) {
                        ++distinct;
                        s.insert(idx);
                    } else {
                        int oldL = *s.begin();
                        int oldR = *s.rbegin();

                        s.insert(idx);

                        int newL = *s.begin();
                        int newR = *s.rbegin();

                        addRange(newL, oldL, 1);
                        addRange(oldR, newR, 1);
                    }
                }

                nums[idx] = val;
            }

            int best = 0;

            if (small) {
                for (int x : cover)
                    best = max(best, x);
            } else {
                best = seg.maximum();
            }

            answer.push_back(distinct + best);
        }

        return answer;
    }
};
